import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        int total = n * (n - 1) / 2;
        int limit = n * (n - 1);
        int[][] dpTable = new int[n + 1][limit + 1];
        int[][] dp1Table = new int[n + 1][limit + 1];

        dpTable[1][total] = 1;

        for (int i = 2; i <= n; i++) {
            int low = total - (i - 1) * (i - 2) / 2;
            int high = total + (i - 1) * (i - 2) / 2;

            for (int x = low; x <= high; x++) {
                for (int delta = -i + 1; delta < i; delta++) {
                    int idx = x + delta;
                    if (0 <= idx && idx <= limit) {
                        dpTable[i][idx] = (dpTable[i][idx] + (int)((long)dpTable[i - 1][x] * (i - Math.abs(delta)) % mod)) % mod;
                    }
                }
            }

            for (int x = low; x <= high; x++) {
                dp1Table[i][x] = (int)((long)dp1Table[i - 1][x] * i % mod);
            }

            for (int x = low; x <= high; x++) {
                for (int delta = 1; delta < i; delta++) {
                    int idx = x - delta;
                    if (0 <= idx && idx <= limit) {
                        dp1Table[i][idx] = (dp1Table[i][idx] + (int)((long)dpTable[i - 1][x] * (i - delta) % mod)) % mod;
                    }
                }
            }
        }

        long sum = 0;
        for (int x = total + 1; x <= limit; x++) {
            sum = (sum + dp1Table[n][x]) % mod;
        }
        System.out.println(sum);
        scanner.close();
    }
}
